#!/bin/sh
# vic.sh: per ogni etichetta e gruppo di pastiglie, distanza (bordo più vicino) dal proprio disco e dal disco altrui più vicino
S=$(dirname $0)
$S/g.sh js c="(()=>{const ss=[...document.querySelectorAll('.mappa:not(.citta) [data-settore]')];const D=ss.map(s=>{const r=s.querySelector('.settore-punto').getBoundingClientRect();return {id:s.dataset.settore,x:r.x+r.width/2,y:r.y+r.height/2}});const dist=(r,p)=>{const dx=Math.max(r.left-p.x,0,p.x-r.right),dy=Math.max(r.top-p.y,0,p.y-r.bottom);return Math.round(Math.hypot(dx,dy))};const out=[];for(const s of ss){for(const k of ['.settore-nome','.settore-unita']){const e=s.querySelector(k);if(!e)continue;const r=e.getBoundingClientRect();if(!r.width)continue;const mio=dist(r,D.find(d=>d.id===s.dataset.settore));const alt=D.filter(d=>d.id!==s.dataset.settore).map(d=>[d.id,dist(r,d)]).sort((a,b)=>a[1]-b[1])[0];out.push(s.dataset.settore+' '+k+' mio '+mio+' altrui '+alt[1]+' ('+alt[0]+')'+(alt[1]<mio?'  <<< PIÙ VICINO AD ALTRO':''))}}return out.join('\n')})()" | sed 's/^valore: //'
